import{_ as o}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o as d,ag as c}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"深度对比：Superpowers vs OpenSpec vs Spec Kit vs mattpocock/skills","description":"基于源码与 Skill 契约，全景对比 obra/superpowers、Fission-AI/OpenSpec、github/spec-kit 与 mattpocock/skills 的设计哲学、SDD 工作流、触发机制与适用边界。","frontmatter":{"title":"深度对比：Superpowers vs OpenSpec vs Spec Kit vs mattpocock/skills","description":"基于源码与 Skill 契约，全景对比 obra/superpowers、Fission-AI/OpenSpec、github/spec-kit 与 mattpocock/skills 的设计哲学、SDD 工作流、触发机制与适用边界。","domain":"practice","tags":["sdd","superpowers","openspec","spec-kit","mattpocock-skills"]},"headers":[],"relativePath":"zh/practice/sdd-engineering/tools-comparison.md","filePath":"zh/practice/sdd-engineering/tools-comparison.md","lastUpdated":1795764761000}'),s={name:"zh/practice/sdd-engineering/tools-comparison.md"};function r(i,e,n,a,l,p){return d(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="深度对比-superpowers-vs-openspec-vs-spec-kit-vs-mattpocock-skills" tabindex="-1">深度对比：Superpowers vs OpenSpec vs Spec Kit vs mattpocock/skills <a class="header-anchor" href="#深度对比-superpowers-vs-openspec-vs-spec-kit-vs-mattpocock-skills" aria-label="Permalink to &quot;深度对比：Superpowers vs OpenSpec vs Spec Kit vs mattpocock/skills&quot;">​</a></h1><p><strong>结论先行（BLUF）</strong>：四者虽然都以「规格 + Skill/指令」为载体、试图解决 AI 编程失控问题，但本质上处于四个不同的抽象层级——<strong><code>obra/superpowers</code> 是「Agent 行为操作系统」，<code>Fission-AI/OpenSpec</code> 是「增量规格契约编译器与真源库」，<code>github/spec-kit</code> 是「宪法治理的组织级 SDD 平台」，<code>mattpocock/skills</code> 是「资深工程师的战术工具箱」</strong>。</p><h2 id="受众与非目标" tabindex="-1">受众与非目标 <a class="header-anchor" href="#受众与非目标" aria-label="Permalink to &quot;受众与非目标&quot;">​</a></h2><ul><li><strong>写给谁看</strong>：正在为研发团队做 AI 编码工作流选型的架构师、Tech Lead 与工程效能负责人。</li><li><strong>非目标</strong>：本文不比较模型本身的代码生成智商，也不替代各工具的官方安装文档。</li></ul><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li>了解基本的 AI Coding Agent（如 Claude Code、Codex CLI、Cursor、Antigravity 等）工作方式。</li><li>熟悉 Git 分支、Worktree 与基础自动化测试概念。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完本文，你将能够：</p><ol><li>准确区分四大框架在「流程控制权」与「Spec 生命周期」上的根本分歧。</li><li>理解四者如何通过不同机制（<code>SessionStart</code> 引导、CLI Schema、宪法与扩展 Hook、显式/隐式 Skill 分层）驱动 Agent。</li><li>通过同一业务需求的产物对比，做出符合团队现状的理性选型。</li></ol><hr><h2 id="理论部分-四大框架的底层设计哲学" tabindex="-1">理论部分：四大框架的底层设计哲学 <a class="header-anchor" href="#理论部分-四大框架的底层设计哲学" aria-label="Permalink to &quot;理论部分：四大框架的底层设计哲学&quot;">​</a></h2><h3 id="_1-obra-superpowers-强制行为纪律的自动化流水线" tabindex="-1">1. <code>obra/superpowers</code>：强制行为纪律的自动化流水线 <a class="header-anchor" href="#_1-obra-superpowers-强制行为纪律的自动化流水线" aria-label="Permalink to &quot;1. `obra/superpowers`：强制行为纪律的自动化流水线&quot;">​</a></h3><p><code>obra/superpowers</code>（由 Jesse Vincent 创建）的核心假设是：<strong>Agent 天生倾向于走捷径，必须通过前置引导与行为铁律（Iron Laws）将其约束在工程规范内</strong>。</p><ul><li><strong>定位</strong>：完整的软件开发方法论（Methodology），通过 <code>SessionStart</code> Hook 或插件扩展向会话注入 <code>using-superpowers</code> 引导指令，促使 Agent 在处理非平凡任务时优先触发对应 Skill（而非用硬编码程序化状态机锁死运行时）。</li><li><strong>核心流转</strong>：<code>brainstorming</code>（设计对齐；对「把图标改成矢车菊蓝」这类完全明确的简单任务允许直接执行）→ <code>using-git-worktrees</code>（隔离工作区）→ <code>writing-plans</code>（按独立可测试、可审查的交付物拆分任务；通常给出签名、约束与验证命令，不预写完整函数体）→ <code>subagent-driven-development</code> / <code>executing-plans</code> → <code>test-driven-development</code>（红绿重构）→ <code>requesting-code-review</code> → <code>verification-before-completion</code>（证据门禁）→ <code>finishing-a-development-branch</code>。</li><li><strong>典型特征</strong>：<strong>Agent 主导连续推进</strong>。在 <code>subagent-driven-development</code> 中，明确要求「Rulings, not stalls（裁决而非停滞）」，遇到非破坏性歧义时由主控 Agent 做出裁决并记入账本继续推进，避免频繁打断人类。</li></ul><h3 id="_2-fission-ai-openspec-面向存量项目的增量契约引擎" tabindex="-1">2. <code>Fission-AI/OpenSpec</code>：面向存量项目的增量契约引擎 <a class="header-anchor" href="#_2-fission-ai-openspec-面向存量项目的增量契约引擎" aria-label="Permalink to &quot;2. `Fission-AI/OpenSpec`：面向存量项目的增量契约引擎&quot;">​</a></h3><p><code>Fission-AI/OpenSpec</code> 的哲学非常明确：<strong><code>fluid not rigid</code>（流畅而非僵化）、<code>iterative not waterfall</code>（迭代而非瀑布）、<code>built for brownfield not just greenfield</code>（专为存量项目而非仅新建项目打造）</strong>。</p><ul><li><strong>定位</strong>：轻量级 SDD 命令行工具（<code>@fission-ai/openspec</code>）+ 跨平台 Skill 集。它不试图接管 Agent 的编码手艺（例如不强制 TDD），而是专注于<strong>管理「系统当前真实行为」与「本次变更增量（Delta）」之间的一致性</strong>。</li><li><strong>核心流转与 Profile</strong>： <ul><li>默认 <code>core</code> Profile 包含 <code>propose / explore / apply / update / sync / archive</code>；其中 <code>verify</code>、<code>bulk-archive</code> 等命令需启用扩展工作流后才可用。</li><li><strong>宿主调用语法因工具而异</strong>（非终端命令）：例如在 Claude Code 中为 <code>/opsx:propose</code>，在 Cursor 中为 <code>/opsx-propose</code>，在 Codex 中为 <code>$openspec-propose</code>。</li></ul></li><li><strong>典型特征</strong>：<strong>确定性 CLI 结构校验与持久化真源</strong>。所有规格文件采用可读的 Markdown + <code>SHALL/MUST</code> + <code>#### Scenario</code>（WHEN/THEN）格式，由 TypeScript + Zod 编写的 <code>openspec validate &lt;id&gt; --type change --strict --no-interactive</code> 进行结构化静态校验，并通过 <strong>Stores（beta）</strong> 为多仓团队提供只读上游规格上下文。</li></ul><h3 id="_3-github-spec-kit-宪法治理与可扩展的组织级-sdd-平台" tabindex="-1">3. <code>github/spec-kit</code>：宪法治理与可扩展的组织级 SDD 平台 <a class="header-anchor" href="#_3-github-spec-kit-宪法治理与可扩展的组织级-sdd-平台" aria-label="Permalink to &quot;3. `github/spec-kit`：宪法治理与可扩展的组织级 SDD 平台&quot;">​</a></h3><p><code>github/spec-kit</code>（由 GitHub 官方维护，配套 <code>specify-cli</code>）代表了<strong>组织级合规与平台化 SDD 思路</strong>。除核心 SDD 流程外，它还随仓提供需显式安装的 <strong><code>bug</code>（Bug 修复）</strong> 与 <strong><code>assess</code>（想法评估）</strong> 扩展（<code>specify extension add bug</code> / <code>assess</code>），并支持企业通过 <strong>Preset / Extension / Workflow / Bundle / 私有 Catalog（含离线气隙环境）</strong> 进行深度定制。</p><ul><li><strong>定位</strong>：可组装的 SDD 工具链与组织级治理框架（Python 3.11+ / <code>uv</code>）。</li><li><strong>核心流转</strong>：<code>/speckit-constitution</code>（或按宿主语法 <code>/speckit.*</code>、<code>$speckit-*</code>，确立仓库级 <code>.specify/memory/constitution.md</code>）→ <code>/speckit-specify</code> → <code>/speckit-clarify</code> → <code>/speckit-plan</code> → <code>/speckit-checklist</code> → <code>/speckit-tasks</code> → <code>/speckit-analyze</code>（只读跨产物一致性分析）→ <code>/speckit-implement</code> → <code>/speckit-converge</code>（只追加任务直至收敛）。</li><li><strong>典型特征</strong>：<strong>宪法权威（Constitution Authority）与独立恢复</strong>。<code>.specify/memory/constitution.md</code> 被定义为不可协商的最高原则，与它冲突会被 <code>analyze</code> 自动标为 CRITICAL；特性目录通过 <code>SPECIFY_FEATURE_DIRECTORY</code> 或 <code>.specify/feature.json</code> 定位（与 Git 分支 Hook 解耦）；此外还提供独立于斜杠命令的 <code>specify workflow resume</code> 与磁盘检查点恢复能力。</li></ul><h3 id="_4-mattpocock-skills-以人为本的可组合工程原语" tabindex="-1">4. <code>mattpocock/skills</code>：以人为本的可组合工程原语 <a class="header-anchor" href="#_4-mattpocock-skills-以人为本的可组合工程原语" aria-label="Permalink to &quot;4. `mattpocock/skills`：以人为本的可组合工程原语&quot;">​</a></h3><p><code>mattpocock/skills</code>（副标题 <em>Skills for Real Engineers</em>）在 README 中直接批评了接管全流程的框架：<strong>&quot;while doing so, they take away your control and make bugs in the process hard to resolve&quot;</strong>。</p><ul><li><strong>定位</strong>：小而美、可自由裁剪和组合的工程原语库，强调<strong>人类工程师始终掌握架构与设计控制权</strong>。</li><li><strong>核心架构</strong>：区分 <strong>User-invoked（用户显式调用，负责编排）</strong> 与 <strong>Model-invoked（模型可隐式触发、也可由用户显式调用，承载工程纪律）</strong> 两类技能。</li><li><strong>典型特征</strong>：<strong>深度关注软件设计本身</strong>。引入了《领域驱动设计》通用语言（<code>GLOSSARY.md</code> 与 ADR，由 <code>/grill-with-docs</code> 落盘，支持多上下文词表）、John Ousterhout 的深模块理论（<code>codebase-design</code>、<code>improve-codebase-architecture</code>）、示踪弹垂直切片（<code>to-tickets</code>）以及 Issue Tracker 集成（内置 GitHub/GitLab 模板与本地 Markdown，支持按团队流程接入 Linear/Jira）。</li></ul><hr><h2 id="全景维度对比矩阵" tabindex="-1">全景维度对比矩阵 <a class="header-anchor" href="#全景维度对比矩阵" aria-label="Permalink to &quot;全景维度对比矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比维度</th><th><code>obra/superpowers</code></th><th><code>Fission-AI/OpenSpec</code></th><th><code>github/spec-kit</code></th><th><code>mattpocock/skills</code></th></tr></thead><tbody><tr><td><strong>核心隐喻</strong></td><td>Agent 行为操作系统</td><td>增量规格契约编译器与真源库</td><td>宪法治理的 SDD 工具链平台</td><td>工程师战术工具箱</td></tr><tr><td><strong>流程控制权</strong></td><td><strong>提示与纪律强引导</strong>：<code>SessionStart</code> 注入引导，Agent 按约定流转</td><td><strong>契约图驱动</strong>：Artifact DAG 约束产物依赖，人工触发斜杠命令</td><td><strong>宪法与阶段命令驱动</strong>：支持 <code>.specify/extensions.yml</code> Hook</td><td><strong>人类强掌控</strong>：按需显式调用 <code>/grill-me</code>、<code>/to-spec</code> 等原语</td></tr><tr><td><strong>触发机制</strong></td><td><code>SessionStart</code> Hook / 插件注入 <code>using-superpowers</code></td><td>CLI 生成各宿主命令（如 <code>/opsx:propose</code>、<code>$openspec-propose</code>）</td><td><code>specify init</code> 生成 <code>/speckit-*</code> / <code>$speckit-*</code> 命令与脚本</td><td>区分 User-invoked（编排）与 Model-invoked（纪律原语）</td></tr><tr><td><strong>Spec 形态</strong></td><td>对话产出的 <code>Design Doc</code> + <code>writing-plans</code> 任务计划</td><td><code>openspec/changes/&lt;id&gt;/</code> 下的 <code>proposal.md</code> + <code>specs/</code>（Delta）+ <code>design.md</code> + <code>tasks.md</code></td><td><code>.specify/memory/constitution.md</code> + 特性目录 <code>spec.md</code> / <code>plan.md</code> / <code>tasks.md</code></td><td><code>to-spec</code> 发布到 Issue Tracker（含 User Stories、Seam、模块接口决策）</td></tr><tr><td><strong>Spec 生命周期</strong></td><td>随任务结束清理工作区，不维护长期系统规格库</td><td><strong>完整闭环</strong>：<code>propose</code> → <code>apply</code> → <code>archive</code>（Delta 合并入 <code>openspec/specs/</code>）</td><td><strong>写前分析 + 写后收敛</strong>：<code>analyze</code> → <code>implement</code> ↔ <code>converge</code></td><td>沉淀在 Issue Tracker + 仓库 <code>GLOSSARY.md</code> 与 <code>ADRs</code></td></tr><tr><td><strong>任务拆解粒度</strong></td><td>按独立可测试、可审查的交付物拆分（含签名、约束、验证命令）</td><td>按模块分组的 <code>- [ ] X.Y</code> 复选框，要求每组自包含测试与文档</td><td>按阶段组织的 <code>tasks.md</code>，<code>converge</code> 在底部追加 <code>## Phase N: Convergence</code></td><td><strong>示踪弹垂直切片（Tracer-bullet）</strong>：每个 Ticket 贯穿全栈且可独立验证</td></tr><tr><td><strong>并发与隔离</strong></td><td><code>using-git-worktrees</code> + <code>subagent-driven-development</code>（串行任务队列 + 独立子代理）</td><td>独立 Change 目录隔离并发变更（<code>bulk-archive</code> 需启用扩展流）</td><td>通过 <code>SPECIFY_FEATURE_DIRECTORY</code> / <code>.specify/feature.json</code> 隔离特性目录</td><td><code>implement-spec</code> 基于任务依赖图（DAG）对 <strong>Ready Frontier</strong> 并发派发 Worktree 子代理</td></tr><tr><td><strong>跨仓与存量适配</strong></td><td>偏单仓会话级执行</td><td><strong>强</strong>：专为 Brownfield 设计，<code>--json --no-scenarios</code> 省 Token；**Stores（beta）**提供只读跨仓上下文</td><td>通过 <strong>Preset / Bundle / Private Catalog</strong> 适配组织级规范与离线环境</td><td>依赖 <code>setup-matt-pocock-skills</code> 绑定 Issue Tracker，跨仓靠 Tracker 协调</td></tr><tr><td><strong>质量校验手段</strong></td><td>行为铁律（TDD、完工证据门禁）+ 单任务 Reviewer 查 Spec 与质量</td><td><strong>确定性 CLI 结构校验</strong>（<code>openspec validate --strict</code>）+ 可选 <code>verify</code></td><td><code>analyze</code> 只读一致性审查 + <code>converge</code> 现状补漏 + <code>checklist</code> + 扩展 Hook</td><td>预确认测试边界（Seam）+ 双轴并行 <code>code-review</code> + <code>improve-codebase-architecture</code></td></tr></tbody></table><hr><h2 id="可运行示例-同一需求在四者中的产物与校验对比" tabindex="-1">可运行示例：同一需求在四者中的产物与校验对比 <a class="header-anchor" href="#可运行示例-同一需求在四者中的产物与校验对比" aria-label="Permalink to &quot;可运行示例：同一需求在四者中的产物与校验对比&quot;">​</a></h2><p>假设需求为：<strong>「允许管理员按起始日期导出项目审计日志为 CSV」</strong>。四者产出的核心工件差异如下：</p><table tabindex="0"><thead><tr><th>框架</th><th>核心产物路径 / 形态</th><th>关键检查点 / 可复现校验命令</th></tr></thead><tbody><tr><td><code>superpowers</code></td><td>对话确认的 Design Doc + <code>writing-plans</code> 任务列表（每步含测试命令与预期输出）</td><td>执行 <code>tdd</code> 看红灯，完工前运行测试与构建命令并核对退出码 <code>0</code></td></tr><tr><td><code>OpenSpec</code></td><td><code>openspec/changes/export-audit-csv/</code> 下的 <code>proposal.md</code>、<code>specs/audit-export/spec.md</code>、<code>design.md</code>、<code>tasks.md</code></td><td><code>openspec validate export-audit-csv --type change --strict --no-interactive</code>（结构/格式门禁）</td></tr><tr><td><code>spec-kit</code></td><td><code>.specify/memory/constitution.md</code> + 特性目录下的 <code>spec.md</code>、<code>plan.md</code>、<code>tasks.md</code></td><td>运行 <code>/speckit-analyze</code>（只读查矛盾）与 <code>/speckit-converge</code>（补齐未实现任务）</td></tr><tr><td><code>mattpocock/skills</code></td><td><code>GLOSSARY.md</code>（定义 <code>AuditLog</code>）+ Tracker Spec（锁定 HTTP 边界 Seam）+ 垂直切片 Ticket</td><td>在预确认 Seam 写垂直切片测试；提交后运行双轴 <code>code-review</code></td></tr></tbody></table><hr><h2 id="实际用例与适用边界" tabindex="-1">实际用例与适用边界 <a class="header-anchor" href="#实际用例与适用边界" aria-label="Permalink to &quot;实际用例与适用边界&quot;">​</a></h2><ul><li><strong>优先选 <code>obra/superpowers</code></strong>：团队成员对 AI 工程纪律不熟练，Agent 常跳过测试直接改代码或谎报完成。<strong>边界</strong>：多子代理与逐步审查消耗较高 Token，对简单一次性改色/文案属于过度设计。</li><li><strong>优先选 <code>Fission-AI/OpenSpec</code></strong>：多人协作的存量项目（Brownfield），需要防止并发需求改乱系统既有行为。<strong>边界</strong>：它管住「系统行为契约」，不约束代码内部模块深浅与单测写法。</li><li><strong>优先选 <code>github/spec-kit</code></strong>：强合规、离线/私有化（Air-gapped）或大中型组织，需要统一 <code>.specify/memory/constitution.md</code> 与可编排工作流引擎。<strong>边界</strong>：多阶段命令链较重，且缺少 OpenSpec 的 Delta 自动合并归档模型。</li><li><strong>优先选 <code>mattpocock/skills</code></strong>：资深工程师或已有成熟 Issue Tracker 的团队，最关注领域语言、测试 Seam 与长期架构熵减。<strong>边界</strong>：高度依赖使用者的工程判断力，缺少独立的静态 Schema 校验 CLI。</li></ul><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li><strong>陷阱 1：把四个工具当成互斥的「四选一」</strong>。它们分别覆盖「行为纪律 / 规格真源 / 组织宪法 / 架构设计」，完全可以按需组合。</li><li><strong>陷阱 2：把宿主斜杠命令当成终端 CLI 命令</strong>。<code>/opsx:propose</code>、<code>/speckit-specify</code>、<code>/grill-me</code> 均是在 Agent 对话框中调用的 Skill/Command，只有 <code>openspec validate</code>、<code>specify init</code> 才是终端命令。</li><li><strong>陷阱 3：只装 Skill 文件而不配置仓库上下文</strong>。不建 <code>.specify/memory/constitution.md</code>、<code>GLOSSARY.md</code> 或不跑 <code>/setup-matt-pocock-skills</code>，会让审查与规格工具失去锚点。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>选型只是第一步，真正决定 AI 产出下限的是「质量如何被系统性核验」。请继续阅读 <a href="./sdd-quality-assurance.html">SDD 使用差别与质量保证机制</a>。</p>',37)])])}const S=o(s,[["render",r]]);export{m as __pageData,S as default};
